1	import { loadConfig } from '../config.js'
2	
3	const STANDARD = { id: 'standard', label: 'Standard (3-5 days)', priceCents: 499 }
4	const PICKUP = { id: 'pickup', label: 'Pick up in store', priceCents: 0 }
5	const EXPRESS = { id: 'express', label: 'Express (next day)', priceCents: 1499 }
6	
7	// Options shown at checkout, in display order.
8	export function getShippingOptions(user, { flags, config = loadConfig() } = {}) {
9	  const options = [STANDARD, PICKUP]
10	  if (config.giftWrap) options.push({ id: 'gift', label: 'Gift wrap + standard', priceCents: 899 })
11	  return options
12	}
13	
14	export { EXPRESS }
15

1	// Client for the internal flags service. isEnabled(flag, user) is synchronous: flag rules are
2	// fetched in the background and evaluated locally. Tests pass a fake with the same shape.
3	export function createFlags(rules = {}) {
4	  return {
5	    isEnabled(flag, user) {
6	      const rule = rules[flag]
7	      if (!rule) return false
8	      if (rule.users?.includes(user.id)) return true
9	      return typeof rule.percent === 'number' && (hash(`${flag}:${user.id}`) % 100) < rule.percent
10	    },
11	  }
12	}
13	
14	function hash(text) {
15	  let h = 0
16	  for (const ch of text) h = (h * 31 + ch.charCodeAt(0)) >>> 0
17	  return h
18	}
19

1	// Process-wide settings from the environment. Anything per-user belongs in the flags service.
2	export function loadConfig(env = process.env) {
3	  return {
4	    currency: env.CURRENCY ?? 'USD',
5	    giftWrap: env.GIFT_WRAP === 'on',
6	    freeShippingThresholdCents: Number(env.FREE_SHIPPING_THRESHOLD_CENTS ?? 5000),
7	  }
8	}
9

1	// Product reviews widget, gated by the flags service (rolled out 2026-06).
2	export function showReviews(user, { flags }) {
3	  return flags.isEnabled('product-reviews', user)
4	}
