input.old_string:
test('standard comes first', () => {
  const ids = getShippingOptions({ id: 'u1' }, { flags: createFlags(), config: { giftWrap: false } }).map((o) => o.id)
  assert.equal(ids[0], 'standard')
})

input.new_string:
test('standard comes first', () => {
  const ids = getShippingOptions({ id: 'u1' }, { flags: createFlags(), config: { giftWrap: false } }).map((o) => o.id)
  assert.equal(ids[0], 'standard')
})

test('express hidden by default', () => {
  const ids = getShippingOptions({ id: 'u1' }, { flags: createFlags(), config: { giftWrap: false } }).map((o) => o.id)
  assert.ok(!ids.includes('express'))
})

test('express shown when user is in the flag allowlist', () => {
  const flags = createFlags({ 'express-shipping': { users: ['u1'] } })
  const ids = getShippingOptions({ id: 'u1' }, { flags, config: { giftWrap: false } }).map((o) => o.id)
  assert.deepEqual(ids, ['standard', 'pickup', 'express'])
})
